  1→import { useState, useCallback, useEffect } from 'react';
  2→import type { FolderChild } from '@cipherbox/crypto';
  3→import { createInviteLink, fetchInvitesForItem, revokeInvite } from '../../services/invite.service';
  4→import type { InviteInfo } from '../../services/invite.service';
  5→
  6→type InviteLinkTabProps = {
  7→  item: FolderChild;
  8→  folderKey: Uint8Array;
  9→  ipnsName: string;
 10→  parentFolderId: string;
 11→  isOpen: boolean;
 12→};
 13→
 14→/**
 15→ * Invite Link tab content for the ShareDialog.
 16→ *
 17→ * Allows users to:
 18→ * - Create an invite link (URL auto-copied to clipboard)
 19→ * - View active (unclaimed, unexpired) invite links with metadata
 20→ * - Revoke individual invite links with inline confirm
 21→ *
 22→ * IMPORTANT: The ephemeral private key is NOT stored after creation.
 23→ * The URL is copied to clipboard at creation time only. Existing invites
 24→ * show metadata and revoke action, but NOT a copy action.
 25→ */
 26→export function InviteLinkTab({
 27→  item,
 28→  folderKey,
 29→  ipnsName,
 30→  parentFolderId,
 31→  isOpen,
 32→}: InviteLinkTabProps) {
 33→  const [invites, setInvites] = useState<InviteInfo[]>([]);
 34→  const [invitesLoading, setInvitesLoading] = useState(true);
 35→  const [isCreating, setIsCreating] = useState(false);
 36→  const [error, setError] = useState<string | null>(null);
 37→  const [success, setSuccess] = useState<string | null>(null);
 38→  const [confirmRevokeId, setConfirmRevokeId] = useState<string | null>(null);
 39→  const [revokingId, setRevokingId] = useState<string | null>(null);
 40→
 41→  // Fetch active invites when tab becomes visible
 42→  useEffect(() => {
 43→    if (!isOpen) return;
 44→
 45→    let cancelled = false;
 46→    setInvitesLoading(true);
 47→    setInvites([]);
 48→    setError(null);
 49→
 50→    fetchInvitesForItem(ipnsName)
 51→      .then((result) => {
 52→        if (!cancelled) {
 53→          setInvites(result);
 54→        }
 55→      })
 56→      .catch((err) => {
 57→        if (!cancelled) {
 58→          console.error('Failed to fetch invites:', err);
 59→          setError('failed to load invite links');
 60→          setInvites([]);
 61→        }
 62→      })
 63→      .finally(() => {
 64→        if (!cancelled) {
 65→          setInvitesLoading(false);
 66→        }
 67→      });
 68→
 69→    return () => {
 70→      cancelled = true;
 71→    };
 72→  }, [isOpen, ipnsName]);
 73→
 74→  const handleCreate = useCallback(async () => {
 75→    setError(null);
 76→    setSuccess(null);
 77→    setIsCreating(true);
 78→
 79→    try {
 80→      const { url } = await createInviteLink({
 81→        item,
 82→        folderKey,
 83→        ipnsName,
 84→        parentFolderId,
 85→      });
 86→
 87→      // Auto-copy URL to clipboard
 88→      let copied = false;
 89→      try {
 90→        await navigator.clipboard.writeText(url);
 91→        copied = true;
 92→      } catch {
 93→        // Clipboard may not be available (e.g., insecure context)
 94→      }
 95→
 96→      // Truncate URL for display
 97→      const displayUrl = url.length > 60 ? `${url.slice(0, 30)}...${url.slice(-20)}` : url;
 98→      setSuccess(
 99→        copied
100→          ? `link copied to clipboard: ${displayUrl}`
101→          : `link created (copy failed -- save this): ${displayUrl}`
102→      );
103→
104→      // Refresh invite list (don't overwrite success on failure)
105→      try {
106→        const updatedInvites = await fetchInvitesForItem(ipnsName);
107→        setInvites(updatedInvites);
108→      } catch {
109→        // List refresh failed, but invite was created successfully
110→      }
111→    } catch (err) {
112→      console.error('Failed to create invite link:', err);
113→      const message = err instanceof Error ? err.message : 'failed to create invite link';
114→      setError(message);
115→    } finally {
116→      setIsCreating(false);
117→    }
118→  }, [item, folderKey, ipnsName, parentFolderId]);
119→
120→  const handleRevoke = useCallback(async (inviteId: string) => {
121→    setRevokingId(inviteId);
122→    setConfirmRevokeId(null);
